        public GridDataRow BuildMainDataRow(UserNameViewStatisticsModel statistic, bool isNormalMode, bool viewByInteger)
        {
            var reportByColumnIndex = 0;
            var dataRow = BuildBaseDataRow(statistic, viewByInteger);
            dataRow.Columns.Insert(reportByColumnIndex++,
                new Columns { Name = "ReportBy", Value = statistic.ReportBy, CellAlignment = HAlignment.Left });
            dataRow.Columns.Insert(reportByColumnIndex,
                new Columns { Name = "ReportById", Value = string.Empty, CellAlignment = HAlignment.Right });
            if (isNormalMode)
            {
                dataRow.Columns.Add(new Columns
                {
                    Name = "HousePositionTaking",
                    Value = string.Empty,
                    CellAlignment = HAlignment.Right
                });
            }

            dataRow.Columns.Add(new Columns
            {
                Name = "AssociatedAccounts",
                Value = string.Empty,
                CellAlignment = HAlignment.Center
            });
            return dataRow;
        }

