        public List<GridDataRow> BuildMainGroupDataRow(UserNameViewGroupStatisticsModel groupStatistics,
            bool isNormalMode, bool viewByInteger)
        {
            var dataRows = new List<GridDataRow>();
            var groupLength = groupStatistics.UserNameViewStatistics.Count;
            for (var i = 0; i < groupLength; i++)
            {
                var item = groupStatistics.UserNameViewStatistics[i];
                var housePositionTaking = viewByInteger
                    ? Math.Round(item.HousePositionTaking, 2, MidpointRounding.AwayFromZero)
                    : item.HousePositionTaking;
                var dataRow = BuildBaseDataRow(item, viewByInteger);
                dataRow.CustomAttr = JsonConvert.SerializeObject(new { item.ReportBy, item.ReportById, item.SiteName });

                if (i == 0)
                {
                    dataRow.Columns.Insert(0,
                        new Columns
                        {
                            Name = "ReportBy",
                            Value = groupStatistics.GroupName,
                            CellAlignment = HAlignment.Left,
                            MergeRowNumber = groupLength
                        });
                    dataRow.Columns.Insert(1,
                        new Columns
                        {
                            Name = "ReportById",
                            Value = groupStatistics.GroupId,
                            CellAlignment = HAlignment.Center,
                            MergeRowNumber = groupLength
                        });
                }

                if (isNormalMode)
                {
                    dataRow.Columns.Add(new Columns
                    {
                        Name = "HousePositionTaking",
                        Value = housePositionTaking,
                        CellAlignment = HAlignment.Right
                    });
                }

                dataRow.Columns.Add(new Columns
                {
                    Name = "AssociatedAccounts",
                    Value = "Link",
                    CellAlignment = HAlignment.Center
                });
                dataRows.Add(dataRow);
            }

            return dataRows;
        }

        public List<GridDataRow> BuildGroupDataRow(UserNameViewGroupStatisticsModel groupStatistics, bool viewByInteger)
        {
            var dataRows = new List<GridDataRow>();
            var groupLength = groupStatistics.UserNameViewStatistics.Count;
            for (var i = 0; i < groupLength; i++)
            {
                var firstColumnIndex = 0;
                var item = groupStatistics.UserNameViewStatistics[i];
                var dataRow = BuildBaseDataRow(item, viewByInteger);

                if (i == 0)
                {
                    dataRow.Columns.Insert(firstColumnIndex++,
                        new Columns
                        {
                            Name = "ReportBy",
                            Value = groupStatistics.GroupName,
                            CellAlignment = HAlignment.Left,
                            MergeRowNumber = groupLength
                        });
                }

                dataRow.Columns.Insert(firstColumnIndex,
                    new Columns { Name = "NoOfPlayers", Value = item.NoOfPlayers, CellAlignment = HAlignment.Right });
                dataRows.Add(dataRow);
            }

            return dataRows;
        }
